#!/usr/bin/env node
/**
 * migrate-to-subpaths.mjs
 *
 * Codemod: mengubah semua import/export-from bernama dari root "@railfinance/core"
 * menjadi subpath export granular (@railfinance/core/ui/*, /lib, /auth, dst).
 *
 * Statement-level parser: menangani statement satu-baris dan multi-baris.
 * Simbol dengan kind "type" otomatis diimpor sebagai type-only import
 * (kompatibel verbatimModuleSyntax). Simbol tak dikenal tetap di root (dilaporkan).
 *
 * Mapping digenerate dari ekspor aktual @railfinance/core
 * (lihat progress-report-chunk-optimization.md).
 *
 * Usage:
 *   node scripts/migrate-to-subpaths.mjs [--dry-run]
 */

